INSERT INTO tarot_cards (id, deck_order, arcana_type, major_number, suit, rank_number, name, image_path, meaning, advice, yes_no, yes_no_meaning) VALUES
  ('fool', 0, 'major', 0, NULL, NULL, 'The Fool', '/cards/fool.svg', 'A blank page and a leap of faith — a new journey begins with an open heart.', 'Trust the path before you and take that first step, even without all the answers.', 'maybe', 'A new beginning rarely carries a fixed answer — the outcome depends on the step you take.'),
  ('magician', 1, 'major', 1, NULL, NULL, 'The Magician', '/cards/magician.svg', 'You hold all the tools you need. Focus your will and turn intention into action.', 'Use your skills and resources deliberately — now is the time to make it happen.', 'yes', 'You already hold everything needed — the energy supports moving forward with focus.'),
  ('high-priestess', 2, 'major', 2, NULL, NULL, 'The High Priestess', '/cards/high-priestess.svg', 'Quiet wisdom hides beneath the surface. Listen to your intuition and inner voice.', 'Pause, go inward, and let your instincts guide you before you act.', 'uncertain', 'The answer is hidden below the surface for now — trust your intuition rather than forcing a clear yes or no.'),
  ('empress', 3, 'major', 3, NULL, NULL, 'The Empress', '/cards/empress.svg', 'Growth, abundance, and nurturing energy surround you. Let beauty and care flourish.', 'Be patient and generous — create with love and let things ripen naturally.', 'yes', 'Growth, abundance and nurturing energy back your wish — the answer is a quiet yes.'),
  ('emperor', 4, 'major', 4, NULL, NULL, 'The Emperor', '/cards/emperor.svg', 'Structure, authority, and steady leadership. Build on solid ground with discipline.', 'Take charge with a clear plan; firm boundaries bring lasting stability.', 'yes', 'Structure, authority and steady discipline stand behind a confident yes.'),
  ('hierophant', 5, 'major', 5, NULL, NULL, 'The Hierophant', '/cards/hierophant.svg', 'Tradition and trusted guidance offer a reliable path. Learn from what has come before.', 'Follow established wisdom and seek counsel from those you trust.', 'yes', 'Tradition and trusted guidance point to a reliable yes — lean on what has already proven itself.'),
  ('lovers', 6, 'major', 6, NULL, NULL, 'The Lovers', '/cards/lovers.svg', 'A meaningful bond or an important choice. Follow what your heart truly values.', 'Choose with honesty and alignment — connection deepens when you are sincere.', 'yes', 'Your heart and values are aligned here — the answer is yes, especially when you choose with honesty.'),
  ('chariot', 7, 'major', 7, NULL, NULL, 'The Chariot', '/cards/chariot.svg', 'Willpower and momentum carry you forward. Stay focused and you will prevail.', 'Keep your eyes on the goal and steer with confidence through every obstacle.', 'yes', 'Willpower and momentum are on your side — a focused yes, provided you stay committed.'),
  ('strength', 8, 'major', 8, NULL, NULL, 'Strength', '/cards/strength.svg', 'True power is gentle — patience, courage, and compassion tame any challenge.', 'Lead with calm strength; a soft hand is often the strongest one.', 'yes', 'Gentle courage and patient resolve make this a yes — lead with calm, not force.'),
  ('hermit', 9, 'major', 9, NULL, NULL, 'The Hermit', '/cards/hermit.svg', 'Time to step back and seek inner clarity. Solitude now brings deeper answers.', 'Turn inward, reflect, and let the quiet reveal what you truly need.', 'no', 'Not yet — the card asks you to step back and find inner clarity before acting.'),
  ('wheel-of-fortune', 10, 'major', 10, NULL, NULL, 'Wheel of Fortune', '/cards/wheel-of-fortune.svg', 'Fortune turns and cycles shift. What changes now is part of a larger rhythm.', 'Ride the tide with flexibility — embrace the turn, good or otherwise.', 'maybe', 'Fortune is turning — the result depends on how you ride the change rather than a fixed yes or no.'),
  ('justice', 11, 'major', 11, NULL, NULL, 'Justice', '/cards/justice.svg', 'Truth and fairness carry the day. Cause and effect now come into balance.', 'Act with honesty and weigh both sides; the scales will settle fairly.', 'maybe', 'The scales are still weighing — the fair answer depends on the facts and your honesty.'),
  ('hanged-man', 12, 'major', 12, NULL, NULL, 'The Hanged Man', '/cards/hanged-man.svg', 'A necessary pause. Release control and see the situation from a new angle.', 'Stop pushing — surrender to the moment and let a fresh perspective arrive.', 'no', 'Pause is needed first — forcing this now would only hold back a clearer answer.'),
  ('death', 13, 'major', 13, NULL, NULL, 'Death', '/cards/death.svg', 'An ending clears the way for renewal. Release what has served its time.', 'Let go without regret; a profound transformation is opening a new door.', 'no', 'An ending is clearing the way — the current path is closing so a new one can begin.'),
  ('temperance', 14, 'major', 14, NULL, NULL, 'Temperance', '/cards/temperance.svg', 'Balance and patience bring harmony. Blend opposites with grace.', 'Move in moderation and keep your cool — steady steps reach the destination.', 'yes', 'Balance and patience bring harmony — a measured yes, taken one steady step at a time.'),
  ('devil', 15, 'major', 15, NULL, NULL, 'The Devil', '/cards/devil.svg', 'Beware of attachment, temptation, or a binding pattern. Recognize the chains.', 'Name what holds you and reclaim your freedom — the chain only binds if you allow it.', 'no', 'Attachment or a binding pattern stands in the way — not yet, until the chain is named and broken.'),
  ('tower', 16, 'major', 16, NULL, NULL, 'The Tower', '/cards/tower.svg', 'Sudden change shatters the false and reveals the truth. What falls was never meant to stand.', 'Welcome the shake-up; out of the rubble a clearer foundation can be built.', 'no', 'Sudden change is shattering the old — the ground must settle before a steady yes is possible.'),
  ('star', 17, 'major', 17, NULL, NULL, 'The Star', '/cards/star.svg', 'Hope, healing, and quiet inspiration renew your spirit after the storm.', 'Trust the light ahead and keep believing — your wishes are within reach.', 'yes', 'Hope and quiet renewal point to yes — trust the light ahead and keep your wish alive.'),
  ('moon', 18, 'major', 18, NULL, NULL, 'The Moon', '/cards/moon.svg', 'Illusion and uncertainty blur the way. Trust your intuition, not appearances.', 'Slow down and look deeper; clarity will come when the fog lifts.', 'uncertain', 'Illusion and uncertainty blur the way — the answer is unclear until you look beneath appearances.'),
  ('sun', 19, 'major', 19, NULL, NULL, 'The Sun', '/cards/sun.svg', 'Joy, success, and radiant clarity. Everything is bright and full of life.', 'Celebrate and shine — positive energy attracts the outcomes you desire.', 'yes', 'Joy and radiant clarity confirm a bright yes — everything is working in your favour.'),
  ('judgement', 20, 'major', 20, NULL, NULL, 'Judgement', '/cards/judgement.svg', 'A call to rise, renew, and be honest with yourself. A verdict of awakening.', 'Answer the call with courage; forgive the past and step into your next chapter.', 'yes', 'A call to rise and renew — yes, especially once you forgive the past and answer honestly.'),
  ('world', 21, 'major', 21, NULL, NULL, 'The World', '/cards/world.svg', 'Completion and fulfillment — a cycle closes in perfect wholeness.', 'Celebrate what you have achieved; the door is open to a wider world.', 'yes', 'Completion and wholeness mark this as a fulfilled yes — the cycle closes in your favour.');
